function ImagePreviewPage() {
  const [dialogOpen, setDialogOpen] = useState(false);
  const [deleted, setDeleted] = useState(false);
  const [toast, setToast] = useState(null);

  const image = {
    name: "sunset-over-the-fjord.jpg",
    details: "JPEG · 2.4 MB · 3024 × 2268",
    src:
      "https://images.unsplash.com/photo-1500964757637-c85e8a162699?auto=format&fit=crop&w=1200&q=80",
    alt: "Sunset over a calm fjord with mountains in the distance",
  };

  const openDialog = useCallback(() => setDialogOpen(true), []);
  const closeDialog = useCallback(() => setDialogOpen(false), []);
  const confirmDelete = useCallback(() => {
    setDialogOpen(false);
    setDeleted(true);
    setToast(`"${image.name}" was deleted from your library.`);
  }, [image.name]);

  return (
    <main>
      <h1 className="page-title">Image preview</h1>
      <p className="page-subtitle">Review your image and manage it from here.</p>

      {deleted ? (
        <div className="image-card" role="status" aria-live="polite">
          <div className="image-frame" style={{ aspectRatio: "4 / 3", color: "var(--muted)" }}>
            <span>This image has been deleted.</span>
          </div>
        </div>
      ) : (
        <article className="image-card" aria-labelledby="image-name">
          <div className="image-frame">
            <img src={image.src} alt={image.alt} />
          </div>
          <div className="image-meta">
            <div className="image-info">
              <span id="image-name" className="image-name">{image.name}</span>
              <span className="image-details">{image.details}</span>
            </div>
            <div className="actions">
              <button type="button" className="btn btn-ghost" aria-label={`Download ${image.name}`}>
                <Icon name="download" />
                <span aria-hidden="true">Download</span>
              </button>
              <button
                type="button"
                className="trigger btn btn-danger"
                onClick={openDialog}
                aria-haspopup="dialog"
                aria-expanded={dialogOpen}
                aria-label={`Delete ${image.name}`}
              >
                <Icon name="trash" />
                <span aria-hidden="true">Delete</span>
              </button>
            </div>
          </div>
        </article>
      )}

      <ConfirmDeleteDialog
        open={dialogOpen}
        imageName={image.name}
        onCancel={closeDialog}
        onConfirm={confirmDelete}
      />

      {toast && <Toast message={toast} onDone={() => setToast(null)} />}
    </main>
  );
}

const root = ReactDOM.createRoot(document.getElementById("root"));
root.render(<ImagePreviewPage />);
